</div></div>
<script>
const $=s=>document.querySelector(s), inv={red:10,blue:10,yellow:10,black:10}; let cooling=false, wins=0, monXp=72, monLv=8, heroHp=100, enemyHp=100;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),1800)}
$('#craftBtn').onclick=$('#fire').onclick=()=>$('#craftModal').classList.add('open'); $('#battleBtn').onclick=()=>{heroHp=100;enemyHp=100;$('#heroHp').style.width='100%';$('#enemyHp').style.width='100%';$('#battleModal').classList.add('open')}; $('#inventoryBtn').onclick=()=>toast('Inventar: Beeren & Liquids');
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>b.closest('.modal').classList.remove('open'));
function cooldown(){cooling=true;$('#cooldown').style.display='grid';let n=20;const i=setInterval(()=>{n--;$('#coolText').textContent='Cooldown: '+n+'s';if(n<=0){clearInterval(i);cooling=false;$('#cooldown').style.display='none'}},1000)}
function can(a){return !Object.keys(a).some(k=>inv[k]<a[k])}function spend(a){Object.keys(a).forEach(k=>inv[k]-=a[k]);['red','blue','yellow','black'].forEach(k=>$('#'+k).textContent=inv[k])}
function brew(name,a){if(cooling)return toast('Der Kessel kühlt ab');if(!can(a)){toast('Nicht genug Zutaten');return}spend(a);toast(name+' hergestellt');cooldown();$('#quest').textContent='1 / 1 Liquid hergestellt'}
$('#makeCore').onclick=()=>brew('Verdant Core',{red:10,blue:10,yellow:10,black:10});$('#makeVolt').onclick=()=>brew('Volt Liquid',{blue:8,yellow:8,black:5});$('#makeEmber').onclick=()=>brew('Ember Nectar',{red:12,yellow:6});
function addXp(n){monXp+=n;if(monXp>=100){monXp-=100;monLv++;$('#monLv').textContent=monLv;$('#monName').innerHTML=(monLv===50?'Vapertation':monLv>=20?'Evolution 1':'Sprig')+' · LV <span id="monLv">'+monLv+'</span>';toast(monLv===50?'EVOLUTION: Vapertation!':(monLv===20?'Evolution 1 erreicht!':'Level erhöht!'))}$('#xpbar').style.width=monXp+'%'}
function enemyTurn(){if(enemyHp<=0)return;setTimeout(()=>{let dmg=10+Math.floor(Math.random()*10);heroHp=Math.max(0,heroHp-dmg);$('#heroHp').style.width=heroHp+'%';$('#heroMon').classList.add('hurt');setTimeout(()=>$('#heroMon').classList.remove('hurt'),900);$('#battleLog').textContent='Nightbite trifft — '+dmg+' Schaden';if(heroHp<=0){$('#battleLog').textContent='Niederlage — dein Vapermon kämpft weiter!';setTimeout(()=>{heroHp=100;$('#heroHp').style.width='100%';$('#battleLog').textContent='Bereit für den nächsten Angriff.'},1400)}},500)}
function playerHit(kind){if(enemyHp<=0)return;let dmg=kind==='hit'?18+Math.floor(Math.random()*10):kind==='pulse'?24+Math.floor(Math.random()*8):8+Math.floor(Math.random()*5);if(kind==='guard'){heroHp=Math.min(100,heroHp+12);$('#heroHp').style.width=heroHp+'%';$('#battleLog').textContent='Abwehr aktiviert — +12 Energie';enemyTurn();return}enemyHp=Math.max(0,enemyHp-dmg);$('#enemyHp').style.width=enemyHp+'%';$('#enemyMon').classList.add('hurt');setTimeout(()=>$('#enemyMon').classList.remove('hurt'),900);$('#battleLog').textContent=(kind==='pulse'?'Pulse-Explosion':'Dampfstoß')+' — '+dmg+' Schaden';if(enemyHp<=0){wins++;$('#battleLog').textContent='Sieg! +32 XP verteilt.';addXp(32);$('#quest2').textContent='Besiege '+Math.min(wins+2,2)+' / 2 Vapermon';setTimeout(()=>{enemyHp=100;$('#enemyHp').style.width='100%';$('#battleLog').textContent='Neuer Gegner erscheint.'},1800)}else enemyTurn()}
$('#hit').onclick=()=>playerHit('hit');$('#guard').onclick=()=>playerHit('guard');$('#pulse').onclick=()=>playerHit('pulse');
window.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='e')$('#craftModal').classList.add('open');if(e.key.toLowerCase()==='f')$('#battleModal').classList.add('open');if(e.key.toLowerCase()==='i')toast('Inventar: Beeren & Liquids')});
</script></body></html>
